using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

// EF Core 9 Cosmos DB Breaking Changes Applied:
//
// 1. Discriminator property renamed: EF Core 9 now uses "$type" instead of "Discriminator".
//    For existing documents that already have "Discriminator", you must explicitly configure
//    the old property name to avoid data loss / query failures.
//
// 2. Synchronous I/O is no longer supported: Methods like ToList(), First(), Count() etc.
//    will throw. You MUST use async equivalents (ToListAsync, FirstAsync, CountAsync).

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    public DbSet<Category> Categories => Set<Category>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change fix: EF Core 9 defaults discriminator to "$type".
        // Existing documents use "Discriminator", so we must configure it explicitly.
        modelBuilder.Entity<Product>()
            .HasDiscriminator<string>("Discriminator");

        modelBuilder.Entity<Category>()
            .HasDiscriminator<string>("Discriminator");

        modelBuilder.Entity<Product>().ToContainer("Products");
        modelBuilder.Entity<Category>().ToContainer("Categories");
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

class Category
{
    public string Id { get; set; } = default!;
    public string Title { get; set; } = default!;
}

using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

// EF Core 9 Breaking Change: Synchronous Cosmos DB queries now throw
// InvalidOperationException. All queries must be async.
class ProductService
{
    private readonly CosmosDbContext _db;

    public ProductService(CosmosDbContext db) => _db = db;

    // BEFORE (EF Core 8 - worked but was discouraged):
    //   public List<Product> GetAll() => _db.Products.ToList();
    //   public Product? GetById(string id) => _db.Products.First(p => p.Id == id);
    //   public int Count() => _db.Products.Count();
    //
    // AFTER (EF Core 9 - async is required):
    public async Task<List<Product>> GetAllAsync()
        => await _db.Products.ToListAsync();

    public async Task<Product?> GetByIdAsync(string id)
        => await _db.Products.FirstOrDefaultAsync(p => p.Id == id);

    public async Task<int> CountAsync()
        => await _db.Products.CountAsync();
}

